using MyProjectManagement;
using System.Text.Json.Nodes;
public static class PlanningCompanyTests {
 static void Check(bool ok,string m){if(!ok)throw new Exception(m);}static void Deny(Action f){try{f();}catch(ApiError){return;}throw new Exception("Expected planning validation denial");}
 public static void Run(){var s=new Snapshot{Id=Guid.NewGuid(),Owner=Guid.NewGuid()};Authority.Seed(s.Settings);s.Settings["moduleMaster"]=new JsonArray(new JsonObject{["id"]="fin",["code"]="FIN",["name"]="Finance",["active"]=true});s.Settings["activityMaster"]=new JsonArray(new JsonObject{["id"]="a",["code"]="ACT",["name"]="Work",["typeId"]="implementation",["active"]=true});s.Members["pm"]=new JsonObject{["id"]="pm",["name"]="Planner",["role"]="Project manager",["active"]=true};var project=new JsonObject{["id"]="p",["code"]="P",["name"]="Project",["stageType"]="implementation",["projectManager"]="pm",["lead"]="pm",["companyCount"]=2,["companyWiseProjectTrackingRequired"]=false,["modules"]=new JsonObject{["Finance"]="pm"},["moduleTeams"]=new JsonObject{["Finance"]=new JsonArray("pm")},["companies"]=new JsonArray(new JsonObject{["id"]="c1",["name"]="Alpha",["code"]="A",["modules"]=new JsonObject()},new JsonObject{["id"]="c2",["name"]="Beta",["code"]="B",["modules"]=new JsonObject{["Finance"]="pm"}})};s.Records["project:p"]=project;var policy=new Policy(s,new AppUser(s.Owner,s.Id,"","",true,null,false,false,0,null,""));
 JsonObject Input(bool company,string value=""){var cols=ImplementationPlanImports.Columns.Where(c=>company||c!="Company").ToArray();var vals=new Dictionary<string,JsonNode?>{{"ACTIVITY","Work"},{"PLAN START",1},{"Planned Consumption (days)",.5},{"Planned Consumption (Sessions)",1},{"Responsible","Us"},{"Assigned People","pm"},{"Row Type","Activity"},{"Module","Finance"},{"Activity Code","ACT"},{"Work Mode","Onsite"},{"Hours Classification","Client"},{"Notes",""},{"Company",value}};return new JsonObject{["projectId"]="p",["baselineDate"]=J.Today.ToString("yyyy-MM-dd"),["workWeek"]="all",["headers"]=new JsonArray(cols.Select(c=>(JsonNode?)JsonValue.Create(c)).ToArray()),["rows"]=new JsonArray(new JsonArray(cols.Select(c=>vals[c]?.DeepClone()).ToArray()))};}
 var input=Input(false);input["companyId"]="outside-project";var preview=ImplementationPlanImports.Validate(s,policy,input);Check(J.N(preview,"invalidCount")==0&&J.S(preview["items"]![0]!["payload"],"companyId")=="c1"&&!preview["columns"]!.AsArray().Any(c=>c?.ToString()=="Company"),"Project-wide import has no company requirement and uses project modules/internal link");var copy=s.Copy();ImplementationPlanImports.Apply(copy,new Policy(copy,new AppUser(copy.Owner,copy.Id,"","",true,null,false,false,0,null,"")),input);Check(copy.Records.Values.Any(t=>J.S(t,"implementationPlanRowId")!=""),"Project-wide import still creates linked work");
 project["companyWiseProjectTrackingRequired"]=true;var stale=Input(false);stale["companyTrackingRequired"]=false;Deny(()=>ImplementationPlanImports.Validate(s,policy,stale));Check(J.N(ImplementationPlanImports.Validate(s,policy,Input(true,"Unknown")),"invalidCount")==1,"Unknown company rejected");Check(J.N(ImplementationPlanImports.Validate(s,policy,Input(false)),"invalidCount")==1,"Enabled mode requires company context");var on=Input(true,"B");preview=ImplementationPlanImports.Validate(s,policy,on);Check(J.N(preview,"invalidCount")==0&&J.S(preview["items"]![0]!["payload"],"companyId")=="c2","Company code resolves from selected master");var foreign=Input(true,"Foreign");int count=s.Records.Count;Deny(()=>ImplementationPlanImports.Apply(s,policy,foreign));Check(s.Records.Count==count,"Invalid company import saves nothing");var legacy=Input(false);legacy["companyId"]="c2";Check(J.N(ImplementationPlanImports.Validate(s,policy,legacy),"invalidCount")==0,"Legacy explicit company selection stays supported");
 // Same activity may be planned separately for two registered companies.
 project["companies"]![0]!["modules"]=new JsonObject{["Finance"]="pm"};var multi=Input(true,"c1");var second=Input(true,"c2")["rows"]![0]!.DeepClone();multi["rows"]!.AsArray().Add(second);Check(J.N(ImplementationPlanImports.Validate(s,policy,multi),"invalidCount")==0,"Per-company duplicate identity remains independent");
 JsonObject Generic(bool withCompany,string value=""){var cols=SpreadsheetImports.PlanColumns.Where(c=>withCompany||c!="Company").ToArray();var vals=new Dictionary<string,string>{{"Plan Reference","REF"},{"Project Code","P"},{"Company",value},{"Module","Finance"},{"Activity Code","ACT"},{"Consultant","pm"},{"Planned Start",J.Today.ToString("yyyy-MM-dd")},{"Planned Finish",J.Today.ToString("yyyy-MM-dd")},{"Planned Hours","4"},{"Priority","Medium"},{"Notes",""}};return new JsonObject{["selectedProjectId"]="p",["headers"]=new JsonArray(cols.Select(c=>(JsonNode?)JsonValue.Create(c)).ToArray()),["rows"]=new JsonArray(new JsonArray(cols.Select(c=>(JsonNode?)JsonValue.Create(vals[c])).ToArray()))};}
 Check(J.N(SpreadsheetImports.Validate(s,policy,"project-plan",Generic(false)),"invalidCount")==1,"Generic enabled import requires company");Check(J.N(SpreadsheetImports.Validate(s,policy,"project-plan",Generic(true,"Beta")),"invalidCount")==0,"Generic valid company accepted");project["companyWiseProjectTrackingRequired"]=false;var generic=SpreadsheetImports.Validate(s,policy,"project-plan",Generic(false));Check(J.N(generic,"invalidCount")==0&&!generic["columns"]!.AsArray().Any(c=>c?.ToString()=="Company"),"Generic disabled import accepts no company heading/details");
 var weeklyLookup=SpreadsheetImports.Validate(s,policy,"project-plan",Generic(true,"Beta"),true);Check(weeklyLookup["items"]![0]!["display"]![2]!.ToString()=="Beta","Weekly lookup display retains names for editable preview compatibility");
 Console.WriteLine("PASS v55: company-aware/no-company imports, master references, project modules, legacy context, per-company duplicates, internal links and invalid batch rejection.");}
}
